"use strict";function query(n){$.ajax({url:_global.root+"Report/GetYearlyNexRequest",type:"POST",dataType:"html",data:{empId:$("#EmployeeId").val(),teamid:$("#TeamId").val(),year:$("#Year").val()},beforeSend:function(){n||$(".loading-process").fadeIn(300)},success:function(n){$("#listYearlyNexRequest").html(n);floatThead("table#data")},error:function(){notifyError(_messages.errorTryAgain)},complete:function(){n||$(".loading-process").fadeOut(300)}})}function submitForm(n){$("#IsExportExcel").val(n)}$(document).ready(function(){query(!0);$("#submit").on("click",function(){query(!1)})});$(document).ready(function(){initAutocomplete("#Employee","#EmployeeId");$("form").submit(function(){var n=$("#Employee").val();return n.length===0&&$("#EmployeeId").val(-1),!0})});